from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import x25519
from cryptography.hazmat.primitives.kdf.hkdf import HKDF

RAW = dict(encoding=serialization.Encoding.Raw, format=serialization.PublicFormat.Raw)

def derive(shared, ciphertext):
    return HKDF(algorithm=hashes.SHA256(), length=32, salt=None, info=b"toy-kem" + ciphertext).derive(shared)

def keygen():
    secret = x25519.X25519PrivateKey.generate()
    return secret, secret.public_key()

def encaps(public_key):
    ephemeral = x25519.X25519PrivateKey.generate()
    ciphertext = ephemeral.public_key().public_bytes(**RAW)          # the ciphertext is the one-time public key
    return ciphertext, derive(ephemeral.exchange(public_key), ciphertext)

def decaps(secret_key, ciphertext):
    return derive(secret_key.exchange(x25519.X25519PublicKey.from_public_bytes(ciphertext)), ciphertext)

secret_key, public_key = keygen()
ciphertext, key_sender = encaps(public_key)
key_receiver = decaps(secret_key, ciphertext)
print("ciphertext:", len(ciphertext), "bytes | shared key:", len(key_sender), "bytes | keys equal:", key_sender == key_receiver)

import datetime

TODAY = datetime.date(2026, 10, 4)                     # a fixed reference date so the output is reproducible
CERTIFICATES = [                                       # illustrative inventory, not real certificates
    ("shop.example.test", datetime.date(2027, 1, 20)),
    ("api.example.test", datetime.date(2026, 10, 12)),
    ("legacy.example.test", datetime.date(2026, 9, 28)),
]

def status(not_after):
    days = (not_after - TODAY).days
    if days < 0:
        return days, "EXPIRED"
    if days <= 14:
        return days, "RENEW NOW"
    if days <= 30:
        return days, "renew soon"
    return days, "ok"

for host, not_after in CERTIFICATES:
    days, state = status(not_after)
    print(f"{host:22} expires {not_after}  {days:>4} days  {state}")

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import ChaCha20Poly1305

aead = ChaCha20Poly1305(bytes(range(32)))                          # DEMO key: real keys come from a key exchange
seal = lambda counter, payload: aead.encrypt(counter.to_bytes(12, "big"), payload, None)    # the counter is the nonce
packet = seal(7, b"payload")
print("packet 7 opens:", aead.decrypt((7).to_bytes(12, "big"), packet, None))
try:
    aead.decrypt((8).to_bytes(12, "big"), packet, None)
except InvalidTag:
    print("wrong counter rejected: InvalidTag")

class ReplayWindow:
    def __init__(self, size=64):
        self.size, self.highest, self.seen = size, 0, set()

    def check(self, seq):
        if seq <= self.highest - self.size:
            return "rejected: too old"
        if seq in self.seen:
            return "rejected: replay"
        self.seen.add(seq)
        self.highest = max(self.highest, seq)
        self.seen = {s for s in self.seen if s > self.highest - self.size}
        return "accepted"

window = ReplayWindow()
for seq in (1, 2, 5, 3, 3, 70, 6, 7):
    print(f"packet {seq:>2}: {window.check(seq)}")

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import ec

class ToyHsm:
    """Interface demonstration only. A real HSM enforces 'the key never leaves' in tamper-resistant hardware."""
    def __init__(self):
        self._key = ec.generate_private_key(ec.SECP256R1())

    def public_key(self):
        return self._key.public_key()

    def sign(self, data):
        return self._key.sign(data, ec.ECDSA(hashes.SHA256()))

hsm = ToyHsm()
signature = hsm.sign(b"transaction 42")
hsm.public_key().verify(signature, b"transaction 42", ec.ECDSA(hashes.SHA256()))
print("signature produced by the module verifies with its public key: True")
print("public methods:", [name for name in dir(hsm) if not name.startswith("_")])
